// Auto-generated in-app user manual page — styled to match the platform (Poppins, glass, sidebar-dark).
// Content mirrors docs/user-manual/index.html; images are served from client/public/manual-images/.
import { Link } from 'react-router-dom'

const CSS = ":root{\n    --blue:#2563eb; --blue-700:#1d4ed8; --ink:#0f172a; --muted:#64748b; --faint:#94a3b8;\n    --radius:1rem;\n    --glass-bd:1px solid rgba(255,255,255,.6);\n    --glass-sh:0 20px 25px -5px rgba(15,23,42,.05),0 8px 10px -6px rgba(15,23,42,.05);\n  }\n  *{box-sizing:border-box}\n.manual-page{scroll-behavior:smooth}\n.manual-page{\n    margin:0;min-height:100vh;color:var(--ink);line-height:1.6;-webkit-font-smoothing:antialiased;\n    font-family:'Poppins',ui-sans-serif,system-ui,-apple-system,sans-serif;\n    background:\n      radial-gradient(38rem 38rem at 105% -8%, rgba(37,99,235,.20), transparent 60%),\n      radial-gradient(34rem 34rem at -8% 18%, rgba(99,102,241,.18), transparent 60%),\n      radial-gradient(30rem 30rem at 55% 118%, rgba(14,165,233,.16), transparent 60%),\n      linear-gradient(135deg,#eef2ff 0%,#f8fafc 50%,#eff6ff 100%);\n    background-attachment:fixed;\n  }\n  @keyframes manualFadeInUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n\n  .layout{display:grid;grid-template-columns:264px 1fr;gap:0;max-width:1360px;margin:0 auto}\n\n  /* TOC sidebar — mirrors the app's .sidebar-dark */\n  aside{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;padding:26px 16px;\n    background:\n      radial-gradient(26rem 20rem at 10% -5%, rgba(59,130,246,.28), transparent 60%),\n      linear-gradient(180deg,#131b31 0%,#0d1424 55%,#0a0f1d 100%);\n    backdrop-filter:blur(22px) saturate(160%);-webkit-backdrop-filter:blur(22px) saturate(160%);\n    border-right:1px solid rgba(255,255,255,.08)}\n  aside .brand{display:flex;align-items:center;gap:10px;color:#fff;font-weight:600;font-size:18px;letter-spacing:-.01em;padding:0 10px}\n  aside .brand svg{stroke:#fff}\n  aside .tag{font-size:12px;color:#7c8aa5;margin:2px 0 20px 42px}\n  aside nav{display:flex;flex-direction:column;gap:2px}\n  aside nav a{color:#cbd5e1;text-decoration:none;font-size:14px;font-weight:500;padding:8px 12px;border-radius:12px;\n    transition:background-color .2s,color .2s,transform .2s}\n  aside nav a:hover{background:rgba(255,255,255,.10);color:#fff;transform:translateX(2px)}\n  aside nav a.section{margin-top:16px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#64748b;font-weight:600;pointer-events:none;padding-bottom:2px}\n  aside .foot{margin-top:24px;padding:16px 12px 0;border-top:1px solid rgba(255,255,255,.10);font-size:12px;color:#7c8aa5}\n\n  main{padding:44px 48px;min-width:0;animation:manualFadeInUp .4s cubic-bezier(.16,1,.3,1) both}\n\n  .hero{margin-bottom:10px}\n  .hero .kicker{color:var(--blue);font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:12px}\n  h1{font-size:34px;line-height:1.15;margin:6px 0 10px;letter-spacing:-.02em;font-weight:700;color:var(--ink)}\n  .lede{font-size:17px;color:var(--muted);max-width:68ch}\n  h2{font-size:24px;margin:48px 0 6px;letter-spacing:-.01em;font-weight:700;color:var(--ink);scroll-margin-top:20px}\n  h3{font-size:17px;margin:24px 0 8px;font-weight:600;color:var(--ink)}\n  p{margin:10px 0}\n  section{border-top:1px solid rgba(148,163,184,.22);padding-top:10px}\n  section:first-of-type{border-top:none}\n  a{color:var(--blue-700);text-decoration:none}\n  a:hover{text-decoration:underline}\n  b{color:var(--ink)}\n  i{color:inherit}\n\n  .meta{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0 8px}\n  .pill{font-size:12px;font-weight:500;color:var(--blue-700);background:#eff6ff;border-radius:999px;padding:5px 12px}\n\n  /* Frosted-glass surface used by figures, cards and tables (matches .glass) */\n  figure{margin:22px 0;border-radius:var(--radius);overflow:hidden;\n    background:rgba(255,255,255,.55);backdrop-filter:blur(16px) saturate(160%);-webkit-backdrop-filter:blur(16px) saturate(160%);\n    border:var(--glass-bd);box-shadow:var(--glass-sh)}\n  figure img{display:block;width:100%;height:auto}\n  figcaption{font-size:13px;color:var(--muted);padding:10px 16px;border-top:1px solid rgba(255,255,255,.5)}\n\n  .legend{list-style:none;margin:14px 0 0;padding:0;display:grid;gap:10px}\n  .legend li{display:grid;grid-template-columns:30px 1fr;gap:12px;align-items:start}\n  .badge{width:26px;height:26px;border-radius:50%;color:#fff;font-weight:600;font-size:13px;\n    display:flex;align-items:center;justify-content:center;\n    background:linear-gradient(to bottom,#3b82f6,#2563eb);box-shadow:0 8px 12px -4px rgba(37,99,235,.35)}\n  .legend li b{color:var(--ink)}\n\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n  .card{border-radius:var(--radius);padding:18px 20px;\n    background:rgba(255,255,255,.55);backdrop-filter:blur(16px) saturate(160%);-webkit-backdrop-filter:blur(16px) saturate(160%);\n    border:var(--glass-bd);box-shadow:var(--glass-sh)}\n  .card h3{margin-top:0}\n  .card p{margin:6px 0;font-size:14.5px}\n\n  .callout{border-left:3px solid var(--blue);border-radius:12px;padding:14px 16px;margin:18px 0;\n    background:rgba(239,246,255,.7);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}\n  .callout.warn{border-color:#d97706;background:rgba(255,251,235,.78)}\n  .callout.note{border-color:#94a3b8;background:rgba(241,245,249,.78)}\n  .callout p{margin:4px 0}\n  .callout .h{font-weight:600;display:block;margin-bottom:2px;color:var(--ink)}\n\n  /* Definition tables rendered as glass cards */\n  table.def{width:100%;border-collapse:separate;border-spacing:0;margin:16px 0;font-size:14px;\n    background:rgba(255,255,255,.5);backdrop-filter:blur(16px) saturate(160%);-webkit-backdrop-filter:blur(16px) saturate(160%);\n    border:var(--glass-bd);border-radius:var(--radius);overflow:hidden;box-shadow:var(--glass-sh)}\n  table.def th,table.def td{text-align:left;padding:11px 16px;border-bottom:1px solid rgba(148,163,184,.18);vertical-align:top;line-height:1.5}\n  table.def tr:last-child td{border-bottom:none}\n  table.def th{background:rgba(255,255,255,.45);font-size:11px;letter-spacing:.04em;text-transform:uppercase;color:#334155;font-weight:600}\n  code{background:#eff6ff;color:#1d4ed8;padding:1px 6px;border-radius:6px;font-size:13px;\n    font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}\n\n  .steps{counter-reset:step;list-style:none;padding:0;margin:14px 0}\n  .steps li{position:relative;padding:6px 0 6px 40px;margin:6px 0}\n  .steps li::before{counter-increment:step;content:counter(step);position:absolute;left:0;top:3px;\n    width:26px;height:26px;border-radius:50%;color:#fff;font-size:13px;font-weight:600;\n    display:flex;align-items:center;justify-content:center;\n    background:linear-gradient(180deg,#131b31,#0d1424);box-shadow:0 6px 10px -3px rgba(15,23,42,.3)}\n\n  kbd{background:linear-gradient(180deg,#131b31,#0d1424);color:#fff;border-radius:7px;padding:2px 8px;font-size:12px;font-weight:600}\n  .tag-green{color:#16a34a;font-weight:600}\n  .tag-red{color:#dc2626;font-weight:600}\n  .tag-amber{color:#b45309;font-weight:600}\n\n  footer{margin-top:56px;padding-top:20px;border-top:1px solid rgba(148,163,184,.22);color:var(--muted);font-size:13px}\n\n  @media (max-width:960px){\n    .layout{grid-template-columns:1fr}\n    aside{position:static;height:auto;overflow:visible;border-right:none;border-bottom:1px solid rgba(255,255,255,.08)}\n    aside nav{display:grid;grid-template-columns:1fr 1fr;gap:2px 10px}\n    aside nav a.section{grid-column:1 / -1}\n    main{padding:26px 20px}\n    .grid2{grid-template-columns:1fr}\n    h1{font-size:28px}\n  }\n  @media print{\n    aside{display:none}.layout{grid-template-columns:1fr;max-width:none}\n    main{padding:0;animation:none}figure,section,.card{break-inside:avoid}\n  }\n  .manual-back{position:fixed;top:16px;right:18px;z-index:60;display:inline-flex;align-items:center;gap:7px;\n    padding:9px 15px;border-radius:12px;font-size:13px;font-weight:500;color:#334155;text-decoration:none;\n    background:rgba(255,255,255,.72);backdrop-filter:blur(22px) saturate(170%);-webkit-backdrop-filter:blur(22px) saturate(170%);\n    border:1px solid rgba(255,255,255,.7);box-shadow:0 10px 20px -6px rgba(15,23,42,.18)}\n  .manual-back:hover{background:rgba(255,255,255,.9);text-decoration:none}\n  .manual-back svg{stroke:#334155}\n  @media (max-width:960px){.manual-back{top:12px;right:12px;padding:8px 12px;font-size:12px}}\n  @media print{.manual-back{display:none}}"

const BODY = "<div class=\"layout\">\n  <aside>\n    <div class=\"brand\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19V6l8 6 8-6v13\"/></svg>\n      Platform-CRM\n    </div>\n    <p class=\"tag\">User Manual</p>\n    <nav>\n      <a href=\"#intro\">Overview</a>\n      <a href=\"#concepts\">Key concepts</a>\n      <a href=\"#navigation\">Getting around</a>\n      <a href=\"#controls\">Shared controls</a>\n      <a class=\"section\">Money</a>\n      <a href=\"#dashboard\">Dashboard</a>\n      <a href=\"#daily-sheet\">Daily Sheet</a>\n      <a href=\"#buyers\">Buyers</a>\n      <a href=\"#campaigns\">Campaigns</a>\n      <a href=\"#vendors\">Traffic Source</a>\n      <a href=\"#portal-expenses\">Portal Expenses</a>\n      <a href=\"#complete-report\">Complete Report</a>\n      <a class=\"section\">Team</a>\n      <a href=\"#attendance\">Attendance</a>\n      <a href=\"#queues\">Queues</a>\n      <a href=\"#review\">Review</a>\n      <a href=\"#top-performer\">Top Performer</a>\n      <a href=\"#staff\">Staff Management</a>\n      <a class=\"section\">Administration</a>\n      <a href=\"#users\">Users</a>\n      <a href=\"#system-logs\">System Logs</a>\n      <a class=\"section\">Reference</a>\n      <a href=\"#auth\">Accounts &amp; access</a>\n      <a href=\"#faq\">Tips &amp; FAQ</a>\n    </nav>\n    <div class=\"foot\">Revised 16 Sep 2026<br>Screens use sample data.</div>\n  </aside>\n\n  <main>\n    <div class=\"hero\" id=\"intro\">\n      <div class=\"kicker\">Platform-CRM</div>\n      <h1>User Manual</h1>\n      <p class=\"lede\">Platform-CRM is a pay-per-Lead / Lead-forwarding CRM. Your team records the daily\n      Lead volumes for <b>buyers</b> (the revenue side — Leads sold and forwarded to customers) and\n      <b>campaigns</b> (the cost side — the media buying that sources those Leads). Take the traffic-source\n      payments and the portal bills off that gap and you have your <b>profit</b>. Alongside it runs the team\n      side — attendance, queue coverage, monthly reviews, the month's top performer and the staff roster they\n      all share. This guide walks through every page and the controls you'll use daily.</p>\n      <div class=\"meta\">\n        <span class=\"pill\">13 working pages</span>\n        <span class=\"pill\">Revenue &amp; cost tracking</span>\n        <span class=\"pill\">Live dashboard</span>\n        <span class=\"pill\">Team &amp; attendance</span>\n        <span class=\"pill\">Monthly reviews</span>\n        <span class=\"pill\">CSV / PDF exports</span>\n      </div>\n    </div>\n\n    <!-- CONCEPTS -->\n    <section id=\"concepts\">\n      <h2>Key concepts</h2>\n      <p>A few terms recur across every page. Understanding them makes the whole app read at a glance.</p>\n      <table class=\"def\">\n        <thead><tr><th>Term</th><th>What it means</th></tr></thead>\n        <tbody>\n          <tr><td><b>Buyer</b></td><td>A customer who <i>buys</i> forwarded Leads from you — the <b>revenue</b> side. Buyers have a short code such as <code>RTG 04</code> or <code>L48</code>.</td></tr>\n          <tr><td><b>Campaign</b></td><td>A media-buying campaign that <i>sources</i> Leads — the <b>cost</b> side. Campaigns have codes like <code>C-05</code> and a traffic <b>destination / source</b> such as <code>XXD</code>.</td></tr>\n          <tr><td><b>Traffic source</b></td><td>The vendor a campaign buys its traffic from. Each one has its own payment ledger on the <a href=\"#vendors\">Traffic Source</a> page.</td></tr>\n          <tr><td><b>Answered / Missed</b></td><td>Leads that connected vs. Leads that rang out, for a single day and destination.</td></tr>\n          <tr><td><b>Counted</b></td><td>The billable number of Leads for that row (answered plus any counted replacements).</td></tr>\n          <tr><td><b>Rate</b></td><td>The price per counted Lead, in dollars.</td></tr>\n          <tr><td><b>Total&nbsp;bill</b></td><td>Calculated automatically as <code>Counted × Rate</code>. You never type this — it updates as you edit.</td></tr>\n          <tr><td><b>Portal expenses</b></td><td>What it costs to run the calling portals — a monthly bill per provider. It is an overhead, not a per-Lead cost, so it is counted in whole months.</td></tr>\n          <tr><td><b>Profit / Margin</b></td><td><code>Revenue − Lead cost − portal expenses</code>. A negative number is shown in <span class=\"tag-red\">red</span>.</td></tr>\n          <tr><td><b>Department</b></td><td>The team somebody belongs to (Forwarding, Camps &amp; Flow, Audits…). Set on <a href=\"#staff\">Staff Management</a>; it groups the <a href=\"#review\">Review</a> sheets and the staff views.</td></tr>\n          <tr><td><b>Expected hours</b></td><td>A person's Expected Login and Expected Logout. Every late and early mark in the app is judged against these, and nobody without them is ever marked.</td></tr>\n          <tr><td><b>Flag</b></td><td>One day's verdict for one person — <span class=\"tag-green\">On time</span>, <span class=\"tag-amber\">Late in</span>, <span class=\"tag-amber\">Early out</span> or <span class=\"tag-red\">Late + early</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout note\"><span class=\"h\">The golden rule</span>\n        <p>Almost everything you enter lives on four sheets: the <b>Daily Sheet</b> (revenue), the\n        <b>Campaigns</b> sheet (Lead cost), <b>Traffic Source</b> (what you pay vendors) and\n        <b>Portal Expenses</b> (the monthly overheads). The Dashboard, Buyers and Complete Report pages are\n        all <i>views</i> that summarise those — you rarely edit them directly.</p>\n      </div>\n    </section>\n\n    <!-- NAVIGATION -->\n    <section id=\"navigation\">\n      <h2>Getting around</h2>\n      <p>The dark sidebar on the left is always visible on desktop. It's how you move between pages; the\n      highlighted item is the page you're on. On a phone, tap the <kbd>☰</kbd> menu icon in the top bar to open\n      it. The small <kbd>?</kbd> beside the Platform-CRM logo opens this manual from anywhere.</p>\n      <div class=\"grid2\">\n        <div class=\"card\">\n          <h3>The thirteen working pages</h3>\n          <p><b>Dashboard</b> — the at-a-glance performance overview, with a staff view behind it.</p>\n          <p><b>Daily Sheet</b> — enter and review buyer (revenue) Lead records.</p>\n          <p><b>Buyers</b> — a per-buyer monthly summary with editable rates.</p>\n          <p><b>Campaigns</b> — enter and review campaign (cost) Lead records.</p>\n          <p><b>Traffic Source</b> — per-vendor payment ledgers.</p>\n          <p><b>Portal Expenses</b> — monthly provider expense sheet.</p>\n          <p><b>Complete Report</b> — revenue, cost, overheads and profit side by side.</p>\n          <p><b>Attendance</b> — team check-in / check-out tracking.</p>\n          <p><b>Queues</b> — who covers which forwarding and camp queues.</p>\n          <p><b>Review</b> — monthly performance, behaviour and department reviews, plus Top Performer.</p>\n          <p><b>Staff Management</b> — the staff roster, attendance, leaves and salaries.</p>\n          <p><b>Users</b> and <b>System Logs</b> — administration, and only when sign-in is switched on.</p>\n        </div>\n        <div class=\"card\">\n          <h3>Reading a page</h3>\n          <p>Every page opens with a <b>title</b> and short subtitle at the top-left, and its main\n          <b>controls</b> (date range, month, search, exports) at the top-right.</p>\n          <p>Pages that hold more than one sheet carry <b>tabs</b> under the title — Attendance, Queues,\n          Review and Staff Management all work this way.</p>\n          <p>Money is shown in dollars; large counts use thousands separators. Positive changes are\n          <span class=\"tag-green\">green</span>, drops are <span class=\"tag-red\">red</span>.</p>\n          <p>The sidebar only lists pages your account may open, so a shorter list than the one on the left\n          is normal rather than a fault.</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- SHARED CONTROLS -->\n    <section id=\"controls\">\n      <h2>Shared controls</h2>\n      <h3>The date-range picker</h3>\n      <p>Most money pages carry a date-range button at the top-right (for example\n      <code>2026-04-16 ~ 2026-07-14</code>). Every figure on the page is calculated <i>for that period</i>,\n      so this is the single most important control in the app. <b>Every page opens on today</b> — a wider\n      window is always a deliberate choice.</p>\n      <ol class=\"steps\">\n        <li>Click the date button to open the picker.</li>\n        <li>Pick a quick <b>preset</b> — Today, Yesterday, Last 7 / 30 / 90 days, This month or Last month — or click two days on the calendar for a custom span. Clicking the same day twice gives you that single day.</li>\n        <li>Press <b>Apply</b>. The whole page reloads for the new period.</li>\n      </ol>\n      <h3>Month and day selectors</h3>\n      <p>The monthly sheets — <a href=\"#portal-expenses\">Portal Expenses</a>, <a href=\"#review\">Review</a>,\n      Leaves and Salaries — carry a <b>month</b> selector with <kbd>‹</kbd> <kbd>›</kbd> arrows instead. The\n      attendance sheets carry a <b>day</b> selector with a <b>Today</b> button beside it.</p>\n      <h3>Searching, filtering &amp; sorting</h3>\n      <p>On the sheet pages you can type in the <b>Search</b> box to match a buyer, campaign, person or queue\n      code, use the <b>destination / campaign</b> dropdown to narrow to one entity, and click a\n      <b>column header</b> to sort. Long lists are paged 35 rows at a time.</p>\n      <h3>Editing data</h3>\n      <p>Data is edited <b>inline</b>. On the Daily Sheet and Campaigns sheet each row has a\n      <b>pencil</b> (edit) and <b>trash</b> (delete) button. Everywhere else you type straight into the cell\n      and it saves when you click away; the bottom, faded row of a sheet is always the one that adds a new\n      entry.</p>\n      <h3>Getting the numbers out</h3>\n      <p>The Dashboard exports the period as <b>CSV</b>. The sheet pages export what is on screen as\n      <b>PDF</b> — Queues, Review, all four Staff Management tabs and Attendance each have their own button.\n      System Logs has a <b>Download</b> of the filtered audit trail.</p>\n    </section>\n\n    <!-- DASHBOARD -->\n    <section id=\"dashboard\">\n      <h2>Dashboard</h2>\n      <p>The landing page, laid out to fill <b>one screen</b> with no scrolling: headline numbers along the\n      top, the trend beneath them, three detail cards below that, and every filter and action gathered in a\n      rail down the right-hand side. It answers \"how are we doing this period?\" — change the date range to\n      re-scope all of it.</p>\n      <figure>\n        <img src=\"/manual-images/dashboard.webp\" alt=\"Dashboard with numbered callouts\" width=\"3200\" height=\"2000\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>The Dashboard, scoped to the last 90 days of sample data.</figcaption>\n      </figure>\n      <ul class=\"legend\">\n        <li><span class=\"badge\">1</span><div><b>Navigation sidebar</b> — jump to any page; the current page is highlighted.</div></li>\n        <li><span class=\"badge\">2</span><div><b>KPI cards</b> — Revenue, Expenses, Profit and Counted Leads. Each shows the change <i>vs. the previous period of the same length</i>, the absolute movement, and a per-Lead figure underneath. Hover the <kbd>i</kbd> for exactly what a metric counts.</div></li>\n        <li><span class=\"badge\">3</span><div><b>Trend chart</b> — the period's line with the previous period drawn behind it as a grey ghost, and a marker on the peak day. The dropdown where its title sits switches the metric.</div></li>\n        <li><span class=\"badge\">4</span><div><b>Lead Mix</b> — Answered, Missed, Counted and Answer rate, with <b>Activity</b> and <b>Sources</b> tabs behind them and the revenue / cost / profit per Lead along the bottom.</div></li>\n        <li><span class=\"badge\">5</span><div><b>Answer Rate</b> — Lead quality over the period; a healthy chart keeps the answered bars tall and the missed ones short.</div></li>\n        <li><span class=\"badge\">6</span><div><b>Top Buyers / Campaigns</b> — the period's ranking, switched with the pair of tabs on the card.</div></li>\n        <li><span class=\"badge\">7</span><div><b>Filters rail</b> — the <b>Period</b> picker, the <b>Time bucket</b> (1D / 4D / 1W), the <b>Chart metric</b>, and four actions: <b>Refresh</b>, <b>CSV</b>, <b>Report</b> (jumps to the Complete Report) and <b>Staff</b>.</div></li>\n        <li><span class=\"badge\">8</span><div><b>Team Today</b> — the week strip, then how many are In, Still in, on Break, Late and Absent, and who has not clocked in yet. Pick another day on the strip, or open the full <a href=\"#attendance\">Attendance</a> page from the link at the bottom.</div></li>\n      </ul>\n      <div class=\"callout\"><span class=\"h\">Reading the KPIs</span>\n        <p><b>Expenses</b> is Lead cost <i>plus</i> the portal bills for any month the range covers in full,\n        so it is the same figure the <a href=\"#complete-report\">Complete Report</a> subtracts. A red\n        <b>Profit</b> means the two outran revenue for the window you picked — open the report to see which\n        destinations drove it. Falling Expenses is good news, so that one card's green and red are the other\n        way round.</p>\n      </div>\n\n      <h3>The staff view</h3>\n      <p>The <b>Staff</b> button in the rail slides the whole dashboard sideways to a second view of the same\n      screen — the month's team picture, without leaving the page. <kbd>Esc</kbd> or the <b>Dashboard</b>\n      button at the top-left slides it back.</p>\n      <figure>\n        <img src=\"/manual-images/dashboard-staff.webp\" alt=\"The Dashboard's staff view\" width=\"3200\" height=\"2000\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>The staff view — one card per person, with the month's attendance, review and queue count on each.</figcaption>\n      </figure>\n      <p>Six tiles count the month: <b>Active staff</b>, <b>In today</b>, <b>Late today</b>,\n      <b>Avg performance</b>, <b>Salaries received</b> and <b>Leaves this month</b>. Under them sit the\n      <b>department</b> filter and that month's <b>department review</b> scores, then a card per person\n      carrying their clock times and flag for the day, days in, late days, average hours, their\n      <a href=\"#review\">Review</a> ratings and how many leaves and queues they hold. The search box and the\n      department tabs narrow the grid.</p>\n      <div class=\"callout note\"><span class=\"h\">Why two months are named</span>\n        <p>The heading reads \"attendance, leaves and salary for September 2026 · reviews for August 2026\". A\n        review is always about the month <i>before</i> it is written, so the review figures follow one month\n        behind everything else on the view. That is deliberate, not a mismatch.</p>\n      </div>\n    </section>\n\n    <!-- DAILY SHEET -->\n    <section id=\"daily-sheet\">\n      <h2>Daily Sheet</h2>\n      <p>Your day-to-day workhorse for the <b>revenue</b> side. Each row is one destination's Leads for one\n      day. The <b>Total</b> column and the navy totals bar update automatically from Counted × Rate.</p>\n      <figure>\n        <img src=\"/manual-images/daily-sheet.webp\" alt=\"Daily Sheet with numbered callouts\" width=\"3200\" height=\"2850\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>The Daily Sheet — buyer Lead records for the selected period.</figcaption>\n      </figure>\n      <ul class=\"legend\">\n        <li><span class=\"badge\">1</span><div><b>Search</b> — filter rows by destination code (e.g. type <code>RTG</code>).</div></li>\n        <li><span class=\"badge\">2</span><div><b>Date</b> — the reporting period, shared with the rest of the app.</div></li>\n        <li><span class=\"badge\">3</span><div><b>Destination</b> — narrow the sheet to a single destination, or leave on <i>All destinations</i>.</div></li>\n        <li><span class=\"badge\">4</span><div><b>Column headers</b> — Date, Destination, Answered, Missed, Replacement, Counted, Rate, Total. Click a header (e.g. <b>Rate ↓</b>) to sort by it.</div></li>\n        <li><span class=\"badge\">5</span><div><b>Row actions</b> — the <b>pencil</b> edits a record; the <b>trash</b> deletes it (with a confirm).</div></li>\n        <li><span class=\"badge\">6</span><div><b>Totals &amp; pagination</b> — the navy <b>TOTAL</b> bar sums the filtered set; use <b>Prev / Next</b> to page through 35 rows at a time.</div></li>\n      </ul>\n      <div class=\"callout\"><span class=\"h\">Entering a day's numbers</span>\n        <p>Add or correct records inline on the sheet, then move on — the buyer's Total and every summary\n        that references it (Dashboard, Buyers, Complete Report) update the next time you open them.</p>\n      </div>\n    </section>\n\n    <!-- BUYERS -->\n    <section id=\"buyers\">\n      <h2>Buyers</h2>\n      <p>A rolled-up <b>monthly sheet</b>, one row per buyer, for the selected date range. It's the quickest\n      way to see how much each customer bought and to keep their <b>rate</b> current.</p>\n      <figure>\n        <img src=\"/manual-images/buyers.webp\" alt=\"Buyers monthly sheet\" width=\"3200\" height=\"2120\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Buyers — the Monthly Sheet: per-buyer totals for the period, with inline-editable codes and rates.</figcaption>\n      </figure>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Sr. No.</b></td><td>The row's position, renumbered as the sheet re-sorts. Never stored.</td></tr>\n          <tr><td><b>Buyers</b></td><td>The buyer code. Editable — rename a buyer inline.</td></tr>\n          <tr><td><b>Total Leads Bought</b></td><td>Auto-summed from the Daily Sheet for the chosen date range.</td></tr>\n          <tr><td><b>Average Leads a Day</b></td><td>Total Leads divided by the active days in the period.</td></tr>\n          <tr><td><b>Rates</b></td><td>Price per Lead. <b>Editable</b> — click the cell and type a new value.</td></tr>\n          <tr><td><b>Amount Received</b></td><td>Calculated automatically (Leads × rate).</td></tr>\n        </tbody>\n      </table>\n      <p>The navy <b>TOTAL</b> row sums the sheet — the Rates cell there is the <b>average</b> rate across the\n      period, not a sum — and the band beneath it gives the <b>Total Average Leads a Day</b> for every buyer\n      together.</p>\n      <div class=\"callout note\"><span class=\"h\">Where do new buyers come from?</span>\n        <p>A buyer appears here automatically the first time its code is used on the Daily Sheet — there's no\n        separate \"add buyer\" step, and only buyers with Leads <i>in the selected range</i> are listed, so a\n        buyer who looks missing is usually one the date filter is hiding. Use the <b>Search by name</b> box to\n        find one quickly. Rates edited here are the rates the Daily Sheet, Dashboard and Complete Report all\n        bill at.</p>\n      </div>\n    </section>\n\n    <!-- CAMPAIGNS -->\n    <section id=\"campaigns\">\n      <h2>Campaigns</h2>\n      <p>The mirror image of the Daily Sheet, for the <b>cost</b> side. Each row is a campaign's Leads for one\n      day at a given traffic destination. This is where your media-buying spend is recorded.</p>\n      <figure>\n        <img src=\"/manual-images/campaigns.webp\" alt=\"Campaigns sheet\" width=\"3200\" height=\"1240\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Campaigns — campaign Lead records over a date range, bundled one row per campaign and destination.</figcaption>\n      </figure>\n      <p>The controls match the Daily Sheet: <b>Search</b> by campaign code, a <b>Date</b> range, a\n      <b>Campaign</b> dropdown, sortable headers and a navy <b>TOTAL</b> bar. The extra <b>Destination</b>\n      column names the traffic source the campaign was buying, and the Rate cell in the TOTAL row is the\n      <b>average</b> rate (Total ÷ Counted).</p>\n      <h3>Bundled rows</h3>\n      <p>Over a date range this sheet <b>merges</b> rather than pages. Every record sharing a campaign and a\n      destination collapses into one summed row, so the sheet reads as a cost summary instead of a thousand\n      entries. Matching ignores case, spaces and punctuation — <code>C 03</code>, <code>C-03</code> and\n      <code>c03</code> are all the same campaign — and a small grey <b>50×</b> beside a row says how many\n      records went into it. The line under the sheet keeps the count honest: <i>9 bundled campaign rows from\n      405 records</i>.</p>\n      <div class=\"callout note\"><span class=\"h\">To edit one record, pick one day</span>\n        <p>A bundled row is a sum, so it has no pencil or trash. Set the <b>Date</b> to a single day — click\n        the same day twice in the picker — and the sheet switches to raw, editable rows for that day, with\n        the bottom row adding a new one.</p>\n      </div>\n      <div class=\"callout\"><span class=\"h\">Revenue vs. cost at a glance</span>\n        <p>Daily Sheet totals are your money <i>in</i>; Campaigns totals are your money <i>out</i>. The\n        <a href=\"#complete-report\">Complete Report</a> subtracts one from the other for you.</p>\n      </div>\n    </section>\n\n    <!-- TRAFFIC SOURCE / VENDORS -->\n    <section id=\"vendors\">\n      <h2>Traffic Source</h2>\n      <p>A running <b>payment ledger for each traffic source</b> — the page the sidebar calls <b>Traffic\n      Source</b> and the app calls a vendor's sheet. It opens with one <b>tab per source</b> — the same ones\n      you buy on the <a href=\"#campaigns\">Campaigns</a> sheet (e.g. <code>DXTST</code>, <code>RGR</code>) — so\n      you can track, per vendor, how many Leads converted, what that comes to, and how much has actually been\n      paid.</p>\n      <figure>\n        <img src=\"/manual-images/vendors.webp\" alt=\"Traffic Source page showing a vendor payment ledger\" width=\"3200\" height=\"4552\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Traffic Source — one vendor's tab: a dated ledger with auto Payments, an Average Leads a day, and the automatic colour-coded Due / Advance balance.</figcaption>\n      </figure>\n      <h3>Tabs &amp; the shared date filter</h3>\n      <p>Click a tab along the top to switch vendors. The <b>+</b> tab adds a vendor that isn't in Campaigns —\n      type its name and it behaves exactly like the rest, carrying a small <b>MANUAL</b> badge so you can tell\n      it from the ones Campaigns supplies. One <b>date-range picker</b> at the top-right applies to\n      <i>every</i> tab at once: change it and each vendor's rows and totals re-scope to that period.</p>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Date</b></td><td>The day the entry is for — one row per day you record.</td></tr>\n          <tr><td><b>Traffic Source</b></td><td>Filled in for you — always the current tab's vendor.</td></tr>\n          <tr><td><b>Converted Lead</b></td><td>How many Leads converted that day. You type this.</td></tr>\n          <tr><td><b>Price (Usd)</b></td><td>Price per converted Lead, in dollars. You type this; new rows pre-fill the last price used.</td></tr>\n          <tr><td><b>Payments</b></td><td>Calculated automatically as <code>Converted Lead × Price</code>. You never type this.</td></tr>\n          <tr><td><b>Initial Advance</b></td><td>The running balance <i>after</i> that day, carried down the column from the period's opening figure. Red means you are in debt to the vendor at that point. Calculated for you.</td></tr>\n          <tr><td><b>Amount paid</b></td><td>How much has actually been paid for that day. You type this.</td></tr>\n        </tbody>\n      </table>\n      <h3>Adding &amp; editing rows</h3>\n      <ol class=\"steps\">\n        <li>On the bottom (blank) row, set the <b>Date</b>, then type the <b>Converted Lead</b> count, the <b>Price</b>, and any <b>Amount paid</b>.</li>\n        <li>Press <kbd>Enter</kbd> or click the <b>+</b> at the end of the row to save it.</li>\n        <li>Edit any saved row in place — changes save when you click away; the <b>trash</b> icon removes a row.</li>\n      </ol>\n      <h3>The figures below the sheet</h3>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>Average Leads a Day</h3><p>Total converted Leads ÷ the number of <b>days worked</b> — the days in the period that actually recorded converted Leads, named right beside the figure. It matches how the <a href=\"#buyers\">Buyers</a> sheet works, so the two pages read the same way.</p></div>\n        <div class=\"card\"><h3>Initial Advance</h3><p>The balance the period <b>opens</b> with, and the figure the column of the same name counts down from. You type it once, on your earliest period; after that it <b>carries forward</b> on its own — every new period opens at whatever the previous one closed at, so changing the date range can never throw the figure off. A negative number means the period opened with money owed to the vendor.</p></div>\n        <div class=\"card\"><h3>Amount Due / Advance</h3><p>Worked out for you as <code>Initial Advance + Amount paid − Payments</code>. Positive means the vendor is holding your money, so it reads <span class=\"tag-green\">Advance</span>; negative means you still owe them and it reads <span class=\"tag-red\">Due</span>. There is nothing to pick — the label always follows the figures.</p></div>\n      </div>\n      <div class=\"callout\"><span class=\"h\">Payments vs. Amount paid</span>\n        <p><b>Payments</b> is what the Leads come to (Leads × price); <b>Amount paid</b> is what has actually been\n        settled. The navy <b>Total</b> bar sums Converted Leads, Payments and Amount paid for the period.</p>\n      </div>\n    </section>\n\n    <!-- PORTAL EXPENSES -->\n    <section id=\"portal-expenses\">\n      <h2>Portal Expenses</h2>\n      <p>A <b>monthly expense sheet</b>, one row per provider, for what you spend running the calling portals.\n      Pick a month with the selector at the top-right; the sheet and its charts are for that month.</p>\n      <figure>\n        <img src=\"/manual-images/portal-expenses.webp\" alt=\"Portal Expenses monthly sheet with charts\" width=\"3200\" height=\"2434\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Portal Expenses — the monthly sheet, per-metric provider charts and the month's Total Expenses band.</figcaption>\n      </figure>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Name</b></td><td>The provider / expense line. Type to add or rename.</td></tr>\n          <tr><td><b>Voice Minutes · Rejected Leads · Rent values · Call Recording (USD) · Voip Shield (USD) · Other expenses (USD)</b></td><td>The component amounts that make up the bill. You type each — numbers only. <b>Other expenses</b> is the catch-all for everything left over (payout, fixed float, …).</td></tr>\n          <tr><td><b>Total Amount (Usd)</b></td><td>Defaults to the sum of the component columns, but you can <b>override</b> it for a flat fee.</td></tr>\n          <tr><td><b>% of Total</b></td><td>That row's share of the month's grand total — calculated for you.</td></tr>\n        </tbody>\n      </table>\n      <p>Rows auto-save when you click away, and the bottom row adds a new provider. Below the sheet, a per-metric\n      chart panel compares providers and a navy band shows the month's <b>Total Expenses</b>.</p>\n      <div class=\"callout note\"><span class=\"h\">Auto total, with an override</span>\n        <p>Leave <b>Total Amount</b> alone and it tracks the component columns; type a value to pin a flat\n        amount (e.g. a fixed fee) independent of them.</p>\n      </div>\n      <div class=\"callout\"><span class=\"h\">How it reaches your profit</span>\n        <p>A month's total is charged against profit on the <a href=\"#dashboard\">Dashboard</a> and the\n        <a href=\"#complete-report\">Complete Report</a>, but only for months the date range covers <b>in\n        full</b> — half a month of overheads would be a guess, so the app doesn't make one.</p>\n      </div>\n    </section>\n\n    <!-- COMPLETE REPORT -->\n    <section id=\"complete-report\">\n      <h2>Complete Report</h2>\n      <p>The bottom line. Three stacked sections for the selected period: <b>Revenue</b> by buyer destination,\n      <b>Cost</b> by campaign destination, and a <b>Complete</b> summary that does the arithmetic.</p>\n      <figure>\n        <img src=\"/manual-images/complete-report.webp\" alt=\"Complete Report page\" width=\"3200\" height=\"2714\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Complete Report — revenue and cost combined, with the month's portal expenses taken off to give profit.</figcaption>\n      </figure>\n      <p>Read it top to bottom, following the three labelled bands on the page:</p>\n      <table class=\"def\">\n        <thead><tr><th>Section</th><th>What it shows</th></tr></thead>\n        <tbody>\n          <tr><td><b>REVENUE</b><br><span style=\"color:var(--muted)\">buyer destinations</span></td><td>Every buyer's answered, missed, replacement, counted and total bill, ending in a navy total row.</td></tr>\n          <tr><td><b>COST</b><br><span style=\"color:var(--muted)\">campaign destinations</span></td><td>The same breakdown per campaign and destination — money spent to source the Leads.</td></tr>\n          <tr><td><b>COMPLETE</b><br><span style=\"color:var(--muted)\">revenue − cost − portal expenses = profit</span></td><td>Four cards in a row: Revenue, Cost, Portal Expenses and the Profit they come to. When the two costs exceed revenue the Profit card turns <span class=\"tag-red\">red</span> and shows a negative figure.</td></tr>\n        </tbody>\n      </table>\n      <p>The line under the title counts what went into the report — <i>32 destinations · 9 campaign rows</i> —\n      and the date range at the top-right runs it for any month, quarter or custom window.</p>\n      <div class=\"callout note\"><span class=\"h\">Why Portal Expenses can read $0</span>\n        <p>Only months the period covers from the 1st to the last day are charged. A range that stops\n        mid-month leaves that month's overheads out, so the card can sit at zero on a short window even\n        though the <a href=\"#portal-expenses\">Portal Expenses</a> sheet has rows in it.</p>\n      </div>\n    </section>\n\n    <!-- ATTENDANCE -->\n    <section id=\"attendance\">\n      <h2>Attendance</h2>\n      <p>Tracks team <b>check-in / check-out</b>, fed by a Telegram bot. Staff clock in and out from Telegram;\n      this page turns that into daily rosters and per-member reports. The clock at the top-right is the\n      <b>New York</b> office time the whole page is dated against.</p>\n      <figure>\n        <img src=\"/manual-images/attendance.webp\" alt=\"Attendance page, Day Sheet tab\" width=\"3200\" height=\"2008\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Attendance — the Day Sheet tab: the live strip, five scorecards, the day's exceptions, and the editable day sheet with its Flag and Status columns.</figcaption>\n      </figure>\n      <h3>Three tabs</h3>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>Day Sheet</h3><p>Who is online and who is on a break right now, then cards for <b>Present today</b>, <b>Late logins</b>, <b>Still checked in</b>, <b>Avg hours worked</b> and <b>Off schedule</b>, the day's late arrivals as chips, and panels for <b>Absent</b>, <b>Break overages</b> and <b>Late returns</b>. The table beneath is the day itself, one row per person on the roster and <b>every cell editable</b> — search it, or pick another date with the box on its left.</p></div>\n        <div class=\"card\"><h3>Staff Summary</h3><p>The month per person: present days, attendance rate, on-time and late logins, time lost, early outs, both-ends days, average check-in, total and average hours, and break used. Click a row for that person's day-by-day list.</p></div>\n        <div class=\"card\"><h3>Staff Reports</h3><p><b>XLSX</b> and <b>PDF</b> exports — a team sheet, an all-members report, or a single member's daily breakdown, over whatever period you choose.</p></div>\n      </div>\n      <h3>Recording and correcting a day</h3>\n      <p>One day at a time — the date selector opens on <b>today</b>, because this records a day as it happens.\n      Every person on the roster gets a row.</p>\n      <figure>\n        <img src=\"/manual-images/staff-attendance.webp\" alt=\"Attendance, the Day Sheet tab\" width=\"3200\" height=\"2072\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>The Day Sheet — the day's five scorecards, the month's login band, and a fully editable row per person with its Flag and Status.</figcaption>\n      </figure>\n      <p><b>Every row is editable</b>, whether or not the check-in bot recorded that day. A day the bot recorded\n      arrives filled in; the moment you change anything, your version <b>replaces</b> it <b>everywhere</b> —\n      the cards above the table, <b>Staff Summary</b>, <b>Staff Reports</b> and the <a href=\"#dashboard\">Dashboard</a>\n      all read your figures. A day the bot never recorded at all works the same way: set somebody the bot\n      marked absent to <b>Half day</b> and a half day is what the whole CRM counts. Corrected rows are tinted\n      <b>amber</b>, and the arrow at the end of the row puts the bot's original record back — the bot's own data is\n      never overwritten, which is what makes that possible.</p>\n      <p>People the bot never saw get an empty row that saves itself on the first edit, so opening a roster of\n      thirty does not create thirty blank records. Hours are worked out from the clock times as you type.</p>\n      <p>The <b>Flag</b> column gives each row the day&rsquo;s verdict —\n      <span class=\"tag-green\">On time</span>, <span class=\"tag-amber\">Late in</span>,\n      <span class=\"tag-amber\">Early out</span> or <span class=\"tag-red\">Late + early</span> — against that\n      person&rsquo;s own expected hours, and it moves as you type a correction. The card heading counts the day up,\n      and the <b>PDF</b> export carries the same column. Read the <a href=\"#attendance\">Attendance</a> page for\n      how the verdict is decided; it is decided identically on both pages.</p>\n      <p>Above the table, five <b>scorecards</b> count the day being shown — <b>In</b> out of the roster, then\n      <b>On time</b>, <b>Late in</b>, <b>Early out</b> and <b>Late + early</b> out of the days that could be\n      judged. They are counted from the very rows on screen, so a card can never disagree with the column\n      beneath it.</p>\n      <p>The tinted band under them widens the view to the whole month — <b>On-time logins</b>,\n      <b>Late logins</b>, <b>Time lost</b> and <b>Staff late</b> so far in it — and the\n      <b>Late logins</b> column in the table gives each person their own share of that count. The day's late\n      arrivals are also listed as chips beside it.</p>\n      <p>The <b>Status</b> column shows what is stored for that day. Where nothing is stored yet it shows what\n      the clock times mean, in <i>grey italics</i>: <b>absent</b> for a row with no login, <b>still in</b> for\n      somebody who has logged in but not out, <b>present</b> once they have. Pick a status yourself and it is\n      stored and stops being grey.</p>\n      <div class=\"callout note\"><span class=\"h\">The date is New York&rsquo;s, and Refresh re-reads it</span>\n        <p>Attendance days are days as the <b>New York</b> office reckons them, not your own timezone &mdash; so\n        this tab opens on <i>their</i> today, and if you leave it open past their midnight it moves on to the new\n        day by itself. The check-in bot keeps writing logins and logouts while you sit there, so hit\n        <b>Refresh</b> to pull the day again; the heading says how old the figures on screen are.</p>\n      </div>\n      <h3>Late and early marks</h3>\n      <p>Where a person has <b>expected hours</b> set on <a href=\"#staff\">Staff Management</a>, their clock\n      times are marked here: a login after their expected login reads <span class=\"tag-red\">9:07 AM 7m late</span>,\n      and a logout before their expected logout <span class=\"tag-red\">5:37 PM 23m early</span>. Hover the mark to\n      see the time it was judged against.</p>\n      <p>Anyone with <b>no</b> expected hours set is never marked — a blank schedule means \"not expected at any\n      particular hour\", not \"always on time\". The one exception is the <b>Late check-ins</b> card, which falls back\n      to 9:00 AM for people without a schedule, as it always has.</p>\n      <h3>The flag on a day</h3>\n      <p>Those same two marks are also read as <b>one verdict per day</b>, in a <b>Flag</b> column: a day is\n      <span class=\"tag-green\">On time</span>, <span class=\"tag-amber\">Late in</span>,\n      <span class=\"tag-amber\">Early out</span>, or — when it missed <b>both</b> ends —\n      <span class=\"tag-red\">Late + early</span>. The number of exclamation marks on the badge is the number of\n      marks that fired, so the doubly-bad day is findable without reading a word; hover it for the minutes\n      behind it. A day nobody clocked in for is left blank rather than called on time. As with the individual\n      marks, a logout is only judged where <b>Expected Logout</b> is set, while a login on this page falls back\n      to 9:00 AM — so set both on <a href=\"#staff\">Staff</a> and the flag reads the same on every page.</p>\n      <p>The same flag appears on the <b>Daily Roster</b> table, in the <b>Off schedule</b> card above it, on\n      on the day sheet above, on the <a href=\"#dashboard\">Dashboard</a>'s staff view, and in\n      <b>Staff Summary</b>, where the month is counted per person as <b>On time / Late in / Early out / Both</b>\n      columns.</p>\n      <div class=\"callout note\"><span class=\"h\">Corrections show here too</span>\n        <p>If a day is corrected on the <b>Day Sheet</b>, every tab here shows the\n        corrected figures — the hours, the break, the late and early marks, and who counts as still checked in. The\n        two pages read the same record, so they can never disagree.</p>\n      </div>\n      <div class=\"callout warn\"><span class=\"h\">Needs the attendance service</span>\n        <p>Attendance data is supplied by the external Telegram check-in bot. On an install where that bot and\n        its tables aren't set up yet, the roster reads <i>\"Nobody checked in yet today\"</i> and the counts stay\n        at zero — the check-in and summary features light up once the bot is connected.</p>\n      </div>\n    </section>\n\n    <!-- QUEUES -->\n    <section id=\"queues\">\n      <h2>Queues</h2>\n      <p>Who covers which queues. Two sheets in one page — <b>Forwarding Queues</b> and\n      <b>Camp &amp; Flow Queues</b> — switched with the tabs at the top. They work identically and keep\n      completely separate rows, so the same person can hold a row on both.</p>\n      <figure>\n        <img src=\"/manual-images/queues.webp\" alt=\"Queues page showing the Forwarding Queues sheet\" width=\"3200\" height=\"1264\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Queues — the Forwarding Queues sheet, with the code catalogue folded above it, each person's codes as draggable chips, and the navy TOTAL row beneath.</figcaption>\n      </figure>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Sr. No.</b></td><td>Just the row's position. It renumbers itself and is never stored.</td></tr>\n          <tr><td><b>Name</b></td><td>Picked from the <a href=\"#staff\">Staff</a> roster — you cannot type a free-text name here, which is what keeps every sheet in the app using one spelling.</td></tr>\n          <tr><td><b>Queues</b></td><td>The person's queue codes, shown as chips. Add one from the <b>Edit</b> picker at the end of the row; click a chip's <b>×</b> to remove it.</td></tr>\n          <tr><td><b>Total</b></td><td>How many queues that person covers — counted for you, and summed in the navy row.</td></tr>\n        </tbody>\n      </table>\n      <h3>The code catalogue</h3>\n      <p>The folded <b>Queues</b> panel above the sheet — <i>20 queues · 16 staff</i> — is the list the row\n      pickers are filled from. Press <b>SHOW</b> to open it, then add, rename or remove a code. The add box\n      takes a whole list, so a pasted set such as <code>BHS, BOP Q04, CRM</code> goes in at once, and the\n      catalogue is <b>shared by both sheets</b>. Nothing is assigned here — that happens on the sheet.</p>\n      <h3>Reordering by dragging</h3>\n      <p>Queues are worked in order, so the chips can be <b>dragged</b> into the order you want rather than\n      deleted and re-added. Press and hold a chip, drag it along the row, and let go where it belongs. It works\n      the same way with a finger on a phone or tablet.</p>\n      <h3>Search and History</h3>\n      <p>The <b>search box</b> at the top matches a person or a single queue code, so typing <code>Q04</code>\n      finds everyone covering that queue. The folded <b>History</b> panel at the bottom keeps the last four\n      days a sheet was keyed in, so you can see what the coverage looked like before today's edits. Use the\n      <b>PDF</b> button to print the sheet as it stands.</p>\n      <div class=\"callout\"><span class=\"h\">Adding people and codes</span>\n        <p>The bottom row adds a person from the roster. A queue code that doesn't exist yet is created the\n        first time you use it, so you never have to visit the catalogue first.</p>\n      </div>\n    </section>\n\n    <!-- REVIEW -->\n    <section id=\"review\">\n      <h2>Review</h2>\n      <p>Monthly staff reviews, in four tabs: <b>Performance</b>, <b>Behavior</b>, <b>Department</b> and\n      <b>Top Performer</b>. Rows are grouped under the department each person belongs to, and those\n      departments come from <a href=\"#staff\">Staff Management</a>.</p>\n      <figure>\n        <img src=\"/manual-images/review.webp\" alt=\"Review page, Performance tab, grouped into department bands\" width=\"3200\" height=\"1870\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Review — the Performance tab. Note the heading: the sheet is <b>Reviewing August 2026</b>, the month before it was written.</figcaption>\n      </figure>\n      <div class=\"callout note\"><span class=\"h\">A review is about the month before it</span>\n        <p>A sheet you fill in during <b>September</b> is judging <b>August's</b> work. That is why the month\n        selector opens on <b>last month</b> and the heading names the month being judged — so there is never any\n        doubt which month a score belongs to. The same applies to <a href=\"#staff\">Salaries</a>: a salary paid in\n        September is for August.</p>\n      </div>\n      <table class=\"def\">\n        <thead><tr><th>Tab</th><th>What it records</th></tr></thead>\n        <tbody>\n          <tr><td><b>Performance</b></td><td>A rating and a percentage per person, plus free-text <b>Notes</b>.</td></tr>\n          <tr><td><b>Behavior</b></td><td>The same shape, kept separately so conduct and output are not mixed.</td></tr>\n          <tr><td><b>Department</b></td><td>One score for each department as a whole, for that month.</td></tr>\n          <tr><td><b>Top Performer</b></td><td>Who earns the month's incentive — <a href=\"#top-performer\">its own section below</a>.</td></tr>\n        </tbody>\n      </table>\n      <p>Rows sit under a navy band per department, and the faded row at the foot of each band adds somebody\n      to it. Names are picked from the roster, never typed. Everything saves as you type, each tab has its own\n      <b>PDF</b> export, and long notes wrap inside their column so the table keeps its shape.</p>\n    </section>\n\n    <!-- TOP PERFORMER -->\n    <section id=\"top-performer\">\n      <h2>Top Performer</h2>\n      <p>The fourth tab of the <a href=\"#review\">Review</a> page decides who earns the month's incentive. It\n      scores everybody on the roster against <b>twelve criteria</b> — four of which the CRM can check for\n      itself from the month's own sheets — and ranks them by how many they meet.</p>\n      <figure>\n        <img src=\"/manual-images/top-performer.webp\" alt=\"Review page, Top Performer tab\" width=\"3200\" height=\"4214\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Top Performer — the month's winner and scorecards, the criteria panels, and the ranking with its evidence pills and confirmation chips.</figcaption>\n      </figure>\n      <h3>How a criterion is judged</h3>\n      <p>Four of the twelve are read straight off the month's data and shown as a <b>pill</b>:\n      <span class=\"tag-green\">green</span> met, <span class=\"tag-red\">red</span> not met, grey <b>?</b> when\n      nothing was recorded that month. Hover any pill to see exactly what it was read from.</p>\n      <table class=\"def\">\n        <thead><tr><th>Criterion</th><th>Read from</th></tr></thead>\n        <tbody>\n          <tr><td><b>1 · Exemplary Behavior</b></td><td>Their rating on <a href=\"#review\">Review → Behavior</a> for the month — anything but \"Low Performer\".</td></tr>\n          <tr><td><b>2 · Punctuality</b></td><td><a href=\"#attendance\">Attendance</a> (every day ran to their expected logout) and the Leaves sheet (no Half Day).</td></tr>\n          <tr><td><b>4 · Timely Login</b></td><td>Attendance (no login after their expected login) and the Leaves sheet (no Late Login).</td></tr>\n          <tr><td><b>9 · Goal Achievement</b></td><td><a href=\"#review\">Review → Performance</a> — a rating of Excellent or Good, or a percentage at or above the target you set.</td></tr>\n          <tr><td><b>The other eight</b></td><td>Documentation, Active Participation, Professional Interactions, Written Task Submission, Continuous Learning, Collaboration, Innovation and Feedback Acceptance. Nothing in the CRM records these, so <b>you confirm them</b> per person by tapping the chip.</td></tr>\n        </tbody>\n      </table>\n      <h3>Working the tab</h3>\n      <ol class=\"steps\">\n        <li>Pick the <b>month</b> at the top-right. Criteria 1, 2, 4 and 9 fill themselves in from that month's Review, Attendance and Leaves sheets.</li>\n        <li>Decide which of the <b>additional criteria (8–12)</b> apply this month, with the switches on the right-hand panel. Criteria <b>1–7 always apply</b>. Set the <b>Goal Achievement target</b> — the percentage that counts as met when the rating alone doesn't.</li>\n        <li>Go down the ranking and <b>tap a chip</b> beside a person for each criterion you can confirm. The header chips credit one criterion to everybody shown at once.</li>\n        <li>Whoever meets <b>every criterion in play</b> is marked <b>Eligible for incentive</b> and named in the green banner at the top.</li>\n      </ol>\n      <p>Four scorecards count the month: <b>Eligible for incentive</b>, <b>Pass every automatic check</b>,\n      <b>Average score</b> and <b>Reviewed this month</b>. Only people with a Performance or Behaviour rating\n      picked for the month are listed at all. The list is ranked by criteria met, with the data as tie-breaks,\n      and it <b>re-ranks itself as you tick</b>. The four automatic checks can be confirmed by hand too — tap the\n      pill; navy means your word has replaced the data's. The search box narrows by name or department, and the checkbox beside it hides anybody who\n      fails an automatic check. <b>PDF</b> exports the sheet as it stands.</p>\n      <div class=\"callout note\"><span class=\"h\">Your ticks are shared, and they save themselves</span>\n        <p>The confirmations and the month's switches are kept on the server, not in your browser, so every\n        manager sees the same sheet from any location. It autosaves a moment after each change and says\n        <b>Saved</b>, <b>Saving…</b> or <b>Not saved</b> beside the heading — there is no save button.</p>\n      </div>\n      <div class=\"callout\"><span class=\"h\">Grey \"?\" is not a fail</span>\n        <p>A grey pill means the month has nothing to judge that criterion on — no review written yet, or no\n        attendance recorded. Fill in the <a href=\"#review\">Review</a> sheet or the attendance day and the pill\n        resolves itself. A person can't be eligible while a criterion in play is still unknown.</p>\n      </div>\n    </section>\n\n    <!-- STAFF MANAGEMENT -->\n    <section id=\"staff\">\n      <h2>Staff Management</h2>\n      <p>The <b>one roster</b> that Queues, Review and the Users page all pick their names from, plus the\n      two sheets that hang off it. Three tabs: <b>Staff</b>, <b>Leaves</b> and <b>Salaries</b>. Attendance\n      itself moved to the <a href=\"#attendance\">Attendance</a> page, which is now the one place a day is\n      recorded or corrected.</p>\n      <figure>\n        <img src=\"/manual-images/staff.webp\" alt=\"Staff Management, the Staff roster tab\" width=\"3200\" height=\"2498\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Staff Management — the roster, under its six scorecards, the Departments panel and the month's Top Performer standings.</figcaption>\n      </figure>\n      <h3>Staff</h3>\n      <p>Six scorecards open the tab — <b>Active staff</b>, <b>On leave</b>, <b>Inactive</b>, <b>In today</b>,\n      <b>Late today</b> and <b>Not in yet</b> — and under them sit two panels:</p>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>Departments</h3><p>A card per department with its headcount, who is in it, and how many are in today. The box at the top adds one. Under the cards, today's late arrivals and no-shows are listed as chips, with a link straight to <a href=\"#attendance\">Attendance</a>.</p></div>\n        <div class=\"card\"><h3>Top Performer</h3><p>Last month's standings from <a href=\"#top-performer\">Review → Top Performer</a>, top three, with each person's score out of the criteria in play. The button opens the full tab.</p></div>\n      </div>\n      <p>Below them is the roster itself — add, rename and remove people, and set what each one is.</p>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Name</b></td><td>Add one, or paste a whole list at once to seed a team.</td></tr>\n          <tr><td><b>Departments</b></td><td>A tick-list, not a dropdown — somebody can belong to <b>several</b>. This is what groups them on the Review page.</td></tr>\n          <tr><td><b>Expected Login / Expected Logout</b></td><td>The hours they are expected to keep. Both attendance pages mark a late login and an early logout against these. <b>Leave them blank</b> for anyone without set hours — blank means nothing of theirs is ever marked.</td></tr>\n          <tr><td><b>Status</b></td><td><span class=\"tag-green\">Active</span>, <span class=\"tag-red\">Inactive</span> or <span class=\"tag-amber\">Leave</span>, colour-coded so the column reads at a glance.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout warn\"><span class=\"h\">Renaming affects attendance</span>\n        <p>A person's check-in account is matched to them <b>by name</b> — it is never picked. Renaming somebody\n        re-matches it, so if a new spelling no longer matches the name their check-in bot uses, their attendance\n        stops arriving automatically and has to be keyed in by hand. If someone's days go missing after a rename,\n        that is why; put the spelling back.</p>\n      </div>\n      <h3>Leaves &amp; Salaries</h3>\n      <p><b>Leaves</b> records sick leave, break leave, half days, late logins and anything else, per person per\n      day. Two of those columns are read by <a href=\"#top-performer\">Top Performer</a> — a Half Day counts\n      against Punctuality and a Late Login against Timely Login — so keeping the sheet current keeps that\n      ranking honest. <b>Salaries</b> is one row per person per month — status, amount and a note.</p>\n      <p>Both are monthly sheets about the month just finished, so like Review they open on <b>last month</b>.\n      Every tab has its own <b>PDF</b> export.</p>\n    </section>\n\n    <!-- USERS -->\n    <section id=\"users\">\n      <h2>Users</h2>\n      <p>Where accounts are created and access is handed out. It appears in the sidebar only when sign-in is\n      switched on and your own account is an <b>admin</b>. Nobody is given a password — a new account gets a\n      one-time <b>enrolment link</b> and sets up Google Authenticator from it.</p>\n      <figure>\n        <img src=\"/manual-images/users.webp\" alt=\"Users page\" width=\"3200\" height=\"1456\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Users — the four scorecards, the filter tabs, and one row per account with its access, status and actions.</figcaption>\n      </figure>\n      <p>Four scorecards count the list: <b>Total users</b>, <b>Active</b> (authenticator set up),\n      <b>Pending setup</b> (with how many of their links have expired) and <b>Admins</b>. The tabs beneath\n      filter to <b>All</b>, <b>Admins</b>, <b>Users</b> or <b>Pending</b>.</p>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>User</b></td><td>The account's name, with what it signs in with underneath — an email or a username. <i>· staff</i> marks an account created from somebody on the <a href=\"#staff\">Staff</a> roster.</td></tr>\n          <tr><td><b>Role</b></td><td><b>Admin</b> sees every page and this one; <b>User</b> sees only what it is given.</td></tr>\n          <tr><td><b>Access</b></td><td>How many of the twelve pages the account may open, and which are off. <i>via Finance</i> means the pages come from an access preset rather than being set on the account.</td></tr>\n          <tr><td><b>Status</b></td><td><span class=\"tag-green\">Active</span>, <span class=\"tag-amber\">Pending setup</span> (with how long their link is good for) or <span class=\"tag-red\">Deactivated</span>.</td></tr>\n          <tr><td><b>Last sign-in</b></td><td>When they were last here, or — for somebody who has not enrolled yet.</td></tr>\n        </tbody>\n      </table>\n      <h3>Adding somebody</h3>\n      <ol class=\"steps\">\n        <li>Press <b>Add user</b>, then pick the <b>staff member</b> they are, or type an email or a username. A name is optional.</li>\n        <li>Choose a <b>role</b>, and an <b>access preset</b> if one fits.</li>\n        <li>Save. The app hands you a <b>one-time enrolment link and QR code</b> — send it to them. It is shown once, but <b>Refresh link</b> on their row issues another whenever it goes astray or expires.</li>\n      </ol>\n      <h3>The row actions</h3>\n      <p><b>Reset authenticator</b> issues a fresh enrolment link and stops their current device working — the\n      fix for a lost phone. <b>Refresh link</b> does the same for somebody who has not enrolled yet.\n      <b>Deactivate</b> signs them out and blocks any further login without deleting anything; <b>Activate</b>\n      puts them back. The <b>pencil</b> edits their details, role, preset and page ticks, and the <b>trash</b>\n      deletes the account outright — you can never delete your own. When several people are waiting,\n      <b>Refresh all pending links</b> reissues the lot in one go.</p>\n      <h3>Access presets</h3>\n      <p><b>Access presets</b>, at the top of the page, are named bundles of page access — <i>Agent</i>,\n      <i>Finance</i>, <i>Team lead</i>. Accounts are <b>attached</b> to a preset rather than stamped from it:\n      add a page to the preset and everybody on it gets that page as soon as they reload. The manager shows\n      how many accounts each preset carries, so the reach of an edit is never a guess.</p>\n      <div class=\"callout note\"><span class=\"h\">Detaching is safe</span>\n        <p>Taking an account off a preset — or deleting the preset — copies the pages onto the account first,\n        so nobody's access changes at that moment. From then on their ticks are their own.</p>\n      </div>\n    </section>\n\n    <!-- SYSTEM LOGS -->\n    <section id=\"system-logs\">\n      <h2>System Logs</h2>\n      <p>The audit trail: who did what, when, and what it changed. Like Users, it is admin-only and exists only\n      while sign-in is switched on.</p>\n      <figure>\n        <img src=\"/manual-images/system-logs.webp\" alt=\"System Logs page\" width=\"3200\" height=\"1258\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>System Logs — the filtered trail, newest first. Click any row to open the full detail.</figcaption>\n      </figure>\n      <p>Each row is one action: the <b>time</b>, the <b>user</b> behind it, the <b>action</b> in the app's own\n      naming (<code>record.update</code>, <code>auth.login</code>, <code>user.enroll_link</code>), the\n      <b>entity</b> it touched — named where the app can name it, as in <i>user Lin Zhao</i> — and the HTTP\n      <b>status</b>, green for success, amber for a refusal such as a failed sign-in, red for an error.</p>\n      <p><b>Click a row</b> to expand it: when, user, the request, status, IP address, the entity, the device,\n      and the before-and-after of whatever changed.</p>\n      <h3>Finding one entry among thousands</h3>\n      <p>Four controls at the top narrow the list, and they combine: the <b>date range</b> (which opens on\n      today), the <b>All actions</b> dropdown, and a <b>search</b> across user, action and path. Rows are paged\n      fifty at a time, with the count and <b>Previous / Next</b> at the foot.</p>\n      <div class=\"callout warn\"><span class=\"h\">Download before you clear</span>\n        <p><b>Download</b> saves the entries matching the current filters. <b>Clear</b> deletes them — the\n        filtered set when a filter is on, and <b>every log in the system</b> when none is. Both ask first, and\n        neither can be undone. The trash icon on a row deletes that one entry.</p>\n      </div>\n    </section>\n\n    <!-- AUTH -->\n    <section id=\"auth\">\n      <h2>Accounts &amp; access</h2>\n      <p>Platform-CRM can run fully open (no login) or with authentication switched on. When it's enabled you\n      sign in with your email — or your username — and a 6-digit code from the <b>Google Authenticator</b>\n      app. There is no password to remember, forget or leak.</p>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>Signing in</h3><p>Enter your email or username, then the current 6-digit code from your authenticator app. That's the whole login.</p></div>\n        <div class=\"card\"><h3>Enrolling, once</h3><p>A new account gets a one-time link from an admin. Open it, scan the QR into Google Authenticator — or type the key shown under it — then enter one live code to confirm. You're signed in from there.</p></div>\n        <div class=\"card\"><h3>What you can see</h3><p>Admins see every page. Everyone else sees the pages their account (or its <a href=\"#users\">access preset</a>) grants, and the sidebar lists only those — typing a URL for a page you don't have sends you back to one you do.</p></div>\n        <div class=\"card\"><h3>Admin extras</h3><p>Two more sidebar items: <a href=\"#users\">Users</a> (create accounts, set per-page access, reset authenticators) and <a href=\"#system-logs\">System Logs</a> (the searchable audit trail).</p></div>\n      </div>\n      <div class=\"callout note\"><p>These items only appear when authentication is enabled and you have the rights to see them. If you don't see <b>Users</b> or <b>System Logs</b>, your install is either open or your account isn't an admin — that's expected.</p></div>\n      <div class=\"callout warn\"><span class=\"h\">Lost your phone?</span>\n        <p>Nobody but you ever holds your authenticator secret, so it cannot be looked up or resent. An admin\n        presses <b>Reset authenticator</b> on your row, which invalidates the old device and issues a fresh\n        enrolment link for you to scan.</p>\n      </div>\n    </section>\n\n    <!-- FAQ -->\n    <section id=\"faq\">\n      <h2>Tips &amp; FAQ</h2>\n      <h3>My numbers look tiny / empty</h3>\n      <p>Almost always the <b>date range</b>. Every page opens on <b>today</b>, which can be a single quiet\n      day — widen it (try <b>Last 90 days</b>) and the charts and totals fill in.</p>\n      <h3>I changed a rate but the Dashboard didn't move</h3>\n      <p>Summary pages load their figures when you open them. Press <b>Refresh</b> in the Dashboard's rail, or\n      revisit the page, and it will reflect the new numbers.</p>\n      <h3>A total looks wrong</h3>\n      <p>Totals are always <code>Counted × Rate</code> summed across the <i>filtered</i> rows. Check that your\n      search box and destination filter aren't hiding rows, and that the date range is what you expect.</p>\n      <h3>Profit is worse than revenue minus cost</h3>\n      <p>Because <b>portal expenses</b> come off it too. The <a href=\"#complete-report\">Complete Report</a>\n      shows the three figures side by side, so you can see exactly how much of the gap is overheads.</p>\n      <h3>Portal Expenses shows $0 on the report</h3>\n      <p>Only months your date range covers <b>in full</b> are charged. Widen the range to whole months and the\n      card fills in.</p>\n      <h3>How do I remove a record?</h3>\n      <p>On the Daily Sheet or Campaigns sheet, click the <b>trash</b> icon at the end of the row and confirm.</p>\n      <h3>Somebody's attendance stopped arriving</h3>\n      <p>Almost always a <b>name</b>. A person's check-in account is matched to them by name alone, so if their\n      name on <a href=\"#staff\">Staff</a> was edited and no longer matches the one their check-in bot uses, their\n      days stop coming through. Put the spelling back and they reappear.</p>\n      <h3>Nobody is being marked late</h3>\n      <p>Expected hours have to be set first, on <a href=\"#staff\">Staff Management → Staff</a>. Until a person has\n      an Expected Login, nothing of theirs is marked — that is deliberate, so nobody is called late against hours\n      that were never agreed with them.</p>\n      <h3>Which month does a review or salary belong to?</h3>\n      <p>The month <b>before</b> the one you fill it in. Both pages open on last month and name the month being\n      judged in the heading, so go by that rather than today's date.</p>\n      <h3>Top Performer shows grey \"?\" everywhere</h3>\n      <p>Nothing has been recorded for that month yet. Fill in the <a href=\"#review\">Review</a> sheets and the\n      attendance days and the pills resolve themselves — a criterion the CRM can't judge is never counted as\n      met.</p>\n      <h3>Somebody can't open a page I can</h3>\n      <p>Check their <b>Access</b> on the <a href=\"#users\">Users</a> page. If it reads <i>via</i> a preset, edit\n      the preset instead of the account — that changes it for everybody on it.</p>\n      <h3>A new user says their link doesn't work</h3>\n      <p>Enrolment links expire. Press <b>Refresh link</b> on their row for a fresh one, or\n      <b>Refresh all pending links</b> if several people are waiting.</p>\n    </section>\n\n    <footer>\n      Platform-CRM User Manual · Revised 16 Sep 2026 · Screens captured from sample data on 16 Sep 2026.<br>\n      A pay-per-Lead / Lead-forwarding CRM — Dashboard, Daily Sheet, Buyers, Campaigns, Traffic Source, Portal Expenses, Complete Report, Attendance, Queues, Review, Top Performer, Staff Management, Users &amp; System Logs.\n    </footer>\n  </main>\n</div>\n"

export default function UserManual() {
  return (
    <div className="manual-page">
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <Link to="/" className="manual-back" aria-label="Close user manual">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
        Close
      </Link>
      <div dangerouslySetInnerHTML={{ __html: BODY }} />
    </div>
  )
}
